function UIFeelingCommunicationChatInfoNode:Refresh(data)
    if not data then
        return
    end
    self._data = data
    local headPath
    if data.type == Constants.PhoneChatType.Me then
        local iconId
        local frameId
        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        iconId = playerComponent.playerDojo.playerAvatar
        frameId = playerComponent.playerDojo.playerAvatarFrame
        if checkInt(iconId) == 0 then
            iconId = PlayerInfoUtils.GetDefaultAvatarId(playerComponent.playerDojo.gender)
        end
        if checkInt(frameId) == 0 then
            frameId = PlayerInfoUtils.GetDefaultAvatarFrameId()
        end

        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(iconId)
        if vo then
            headPath = vo.photoPath
        end
    else
        local skinCardId = PhoneUtils.GetRoleCurCardSkinId(data.roleId) 
        headPath =  CardConfMgr:GetInstance():GetCardDefaultSmallHeadPath(skinCardId)
    end
    CfUtils.FillText(self.Text, data.content)
    CfUtils.FillImage(self.ImgHeadIcon, headPath)

    if data.type ~= Constants.PhoneChatType.End then
        self:RefreshSize()
    end
    KTool.SetActive(self.Root, true)
    --if data.type ~= Constants.PhoneChatType.End then
    --    self:ResetAnimator()
    --end
end

--计算大小
function UIFeelingCommunicationChatInfoNode:RefreshSize()
    local count = utf8.len(checkString(self._data.content))
    if count <= 16 then
        self.ImgBubble.sizeDelta = Vector2((22 * count + 30) * 1.5, self.ImgBubble.sizeDelta.y)
        if self._data.type == Constants.PhoneChatType.Me then
            self.Text.alignment = CS.UnityEngine.TextAnchor.UpperLeft
        end
    else
        self.ImgBubble.sizeDelta = Vector2((22 * 16 + 30) * 1.5, self.ImgBubble.sizeDelta.y)
        if self._data.type == Constants.PhoneChatType.Me then
            self.Text.alignment = CS.UnityEngine.TextAnchor.UpperLeft
        end
    end

    local contentGoRt = self.Text.transform:GetComponent(typeof(RectTransform))
    CS.UnityEngine.UI.LayoutRebuilder.ForceRebuildLayoutImmediate(contentGoRt)
    local targetHigth = 190
    if contentGoRt.sizeDelta.y > 116 then
        targetHigth = targetHigth + (contentGoRt.sizeDelta.y - 116) / 37 * 20 --+ 66
    end

    local rt = self.controller.gameObject:GetComponent(typeof(RectTransform))
    rt:SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, targetHigth)
end

